import {mountMobileFan,phoneFlight,PHONE_QUERY} from './mobile-fan.js';
import {deck,shuffleDeck} from './deck.js';
import {createReadingData,buildAIPrompt,positionNotes} from './reading.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let disposeFan=null;
let assets={},state={page:'home',question:'',theme:'自我探索',count:3,draw:[],selected:[],revealed:[],ready:false,busy:false};
const topics={'爱情':'我该如何更清楚地理解这段关系？','事业':'面对当前的工作选择，我需要看清什么？','人际关系':'我可以如何改善当前的人际关系？','自我探索':'此刻的我，最需要关注什么？'};
const referenceQuestions={
  '爱情':['接下来一个月，我可以如何更清楚地表达关系中的需求？','面对这段关系的分歧，我需要留意什么？','我可以如何在亲密关系中建立更合适的边界？'],
  '事业':['未来三个月，我在职业发展上可以优先投入什么？','面对当前的工作选择，我需要权衡哪些因素？','我可以如何改善目前项目中遇到的阻碍？'],
  '人际关系':['我可以如何与朋友更坦诚地沟通当前的分歧？','接下来两周，我可以怎样改善与同事的合作？','在人际交往中，我需要觉察哪些反复出现的模式？'],
  '自我探索':['此刻，我最需要理解的内在需求是什么？','接下来一个月，我可以如何照顾自己的精力与感受？','面对反复出现的犹豫，我可以从哪里开始行动？']
};
function questionSuggestions(text){
  const suggestions=[];
  if((text.match(/[？?]/g)||[]).length>1)suggestions.push('可以先聚焦一个核心问题，让探索更清晰。');
  const timeRange=/(?:[0-9０-９一二两三四五六七八九十百半几数]+\s*(?:个)?\s*(?:小时|天|日|周|星期|月|季度|年)|(?:今天|明天|后天|本周|这周|下周|本月|这个月|下个月|今年|明年|近期|最近|短期|长期|年底|年末|月底|月末|周末)|[0-9]{4}[-/年][0-9]{1,2})/;
  if(text.includes('未来')&&!timeRange.test(text))suggestions.push('可以补充一个时间范围，例如未来一个月。');
  if(/[他她]/.test(text)&&/(?:想什么|在想什么|怎么想|怎么看|喜不喜欢|爱不爱|是否喜欢|是否爱|喜欢我吗|爱我吗)/.test(text))suggestions.push('他人的真实想法无法通过塔罗直接验证，可以结合现实中的沟通与行为观察。');
  return suggestions;
}
try{const r=await fetch('./assets.json');if(!r.ok)throw Error('assets');assets=await r.json()}catch(e){console.warn('牌面清单尚未就绪',e)}
function img(c){const a=assets[c.id];return typeof a==='string'?a:(a?.file||a?.path||a?.image||'')}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function steps(n){return `<nav class="steps" aria-label="占卜步骤">${['提出问题','洗牌与抽牌','聆听解读'].map((t,i)=>`<span class="${i===n?'active':''}">0${i+1} &nbsp; ${t}</span>`).join('')}</nav>`}
function card(c,flipped=false){return `<span class="inner"><span class="back"></span><span class="front ${c.reverse?'reversed':''}"><img src="${esc(img(c))}" alt="${esc(c.name)}${c.reverse?'逆位':'正位'}" loading="eager"></span></span>`}
function go(page){state.page=page;history.pushState({page},'',`#${page}`);render();window.scrollTo({top:0,behavior:'instant'})}
function home(){app.innerHTML=`<section class="hero"><div class="copy"><p class="eyebrow">THE ART OF LOOKING WITHIN</p><h1>答案之外，<br>遇见<em>更深的自己。</em></h1><p class="muted">让思绪安静，让直觉浮现。<br>在七十八张古老意象之间，<br>为此刻的困惑，找到一个新的视角。</p><button class="primary" id="start">开始占卜 <span style="margin-left:32px">⟶</span></button><div class="hero-bottom"><span>✧ 经典韦特塔罗</span><span>◌ 亲手抽取 · 随机相遇</span></div></div><div class="hero-art"><div class="orbit"></div><img class="hero-card" src="${esc(img(deck[17]))}" alt="经典韦特塔罗：星星"><span class="art-label">XVII &nbsp; · &nbsp; THE STAR</span></div></section>`;$('#start').onclick=()=>go('question')}
function question(){app.innerHTML=`<section class="page">${steps(0)}<div class="center"><p class="eyebrow">01 / SET YOUR INTENTION</p><h2>此刻，什么萦绕在你心间？</h2><p class="muted">一个真实的问题，是与自己对话的开始。</p></div><div class="question"><label for="question" class="field-label">你的问题 <span class="muted">· 可以留空，进行开放探索</span></label><textarea id="question" aria-describedby="question-suggestions" maxlength="300" placeholder="例如：面对眼前的选择，我需要看清什么？">${esc(state.question)}</textarea><div id="question-suggestions" class="fine" role="status" aria-live="polite"></div><details><summary class="field-label">如何提问？</summary><ul class="fine"><li>尽量围绕一个核心问题。</li><li>可以补充具体情境和时间范围。</li><li>开放式问题更利于深入探索，但直接的是非问题也允许。</li><li>塔罗不能证实他人的真实想法，也不能保证未来结果。</li></ul></details><details id="reference-questions"><summary class="field-label">参考提问</summary><div id="reference-list" class="themes"></div></details><div class="themes">${Object.keys(topics).map(t=>`<button class="chip ${t===state.theme?'selected':''}" data-theme="${t}">${t}</button>`).join('')}</div><span class="field-label">选择你的牌阵</span><div class="spreads"><button class="spread ${state.count===1?'selected':''}" data-count="1"><span class="mini">▯</span><b>单张 · 此刻的指引</b><small>聚焦一个核心，轻盈地开始</small></button><button class="spread ${state.count===3?'selected':''}" data-count="3"><span class="mini">▯▯▯</span><b>三张 · 内在的路径</b><small>现状 / 阻碍 / 建议</small></button></div><button class="primary wide" id="shuffle">开始洗牌 &nbsp; ⟶</button><p class="fine center">先深呼吸。无须完美的问题，只需要诚实的自己。</p></div></section>`;
const input=$('#question');
const showReferences=()=>{$('#reference-list').innerHTML=referenceQuestions[state.theme].map((text,i)=>`<button class="chip" data-reference="${i}">${esc(text)}</button>`).join('');document.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{state.question=referenceQuestions[state.theme][Number(b.dataset.reference)];input.value=state.question;$('#question-suggestions').textContent='';input.focus()})};
showReferences();input.oninput=e=>{state.question=e.target.value;$('#question-suggestions').textContent=''};input.onblur=()=>{$('#question-suggestions').innerHTML=questionSuggestions(input.value).map(t=>`<p>${esc(t)}</p>`).join('')};document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(chip=>chip.classList.toggle('selected',chip.dataset.theme===state.theme));showReferences()});document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{state.count=Number(b.dataset.count);question()});$('#shuffle').onclick=()=>{state.draw=shuffleDeck();state.selected=[];state.revealed=[];state.ready=false;state.busy=false;go('draw');const currentDraw=state.draw;setTimeout(()=>{if(state.draw!==currentDraw)return;state.ready=true;if(state.page!=='draw')return;$('.fan').classList.remove('shuffling');document.querySelectorAll('.fan button').forEach(b=>b.disabled=false);$('#draw-status').textContent=`牌已展开。请选择 ${state.count} 张与你此刻相遇的牌。`;centerFan()},1700)}}
const position=i=>state.count===1?'此刻的指引':['现状','阻碍','建议'][i];
function centerFan(){if(matchMedia(PHONE_QUERY).matches)return;const w=$('.deck-wrap');if(w)w.scrollLeft=(w.scrollWidth-w.clientWidth)/2}
function draw(){app.innerHTML=`<section class="page ritual">${steps(1)}<div class="center"><p class="eyebrow">02 / TRUST YOUR INTUITION</p><h2><span class="desktop-draw-title">静下心，选择与你相遇的牌。</span><span class="phone-draw-title">静下心，选择你的牌。</span></h2><p class="muted">${state.count===3?'从左至右：现状 · 阻碍 · 建议':'只取一张，倾听此刻的指引'}</p></div><div class="slots">${Array.from({length:state.count},(_,i)=>`<div class="slot"><div class="slot-label">${String(i+1).padStart(2,'0')} · ${position(i)}</div><div id="slot-${i}">${state.selected[i]?selectedMarkup(i):'<div class="placeholder">✧</div>'}</div></div>`).join('')}</div><p class="ritual-note" id="draw-status" role="status">${state.ready?`已选 ${state.selected.length} / ${state.count} 张。点击上方的牌翻面。`:'正在洗牌，让每一种可能重新排列……'}</p><div class="deck-wrap" aria-label="横向滑动浏览完整牌堆"><div class="fan ${state.ready?'':'shuffling'}">${state.draw.map((c,i)=>`<button class="card ${state.selected.includes(c)?'picked':''}" style="--r:${(i-38.5)*1.05}deg;--i:${i};z-index:${i}" aria-label="选择第 ${i+1} 张牌" data-index="${i}" ${state.ready?'':'disabled'}><span class="back"></span></button>`).join('')}</div></div><p class="fine center">78 张完整牌堆 · 手机可左右滑动 · 点击牌背选择，再点击上方翻牌</p><div class="center draw-actions"><button class="primary" aria-describedby="draw-status" id="read" ${state.revealed.filter(Boolean).length===state.count?'':'disabled'}>查看我的解读 &nbsp; ⟶</button><button class="quiet" id="back-question">修改问题</button></div></section>`;
document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.index),b));bindFlips();$('#read').onclick=()=>go('reading');$('#back-question').onclick=()=>go('question');disposeFan=mountMobileFan($('.deck-wrap'),choose);requestAnimationFrame(centerFan)}
function selectedMarkup(i){const c=state.selected[i],on=state.revealed[i];return `<button class="card ${on?'flipped':''}" data-flip="${i}" aria-label="${on?c.name+(c.reverse?'逆位':'正位'):'翻开第'+(i+1)+'张牌'}" aria-pressed="${!!on}">${card(c,on)}</button><div class="card-caption">${on?`${c.name}<small>${c.reverse?'逆位 REVERSED':'正位 UPRIGHT'}</small>`:'点击翻开'}</div>`}
function bindFlips(){document.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>{const i=+b.dataset.flip;if(state.revealed[i]||state.busy)return;state.revealed[i]=true;b.classList.add('flipped');b.setAttribute('aria-pressed','true');const c=state.selected[i];b.setAttribute('aria-label',c.name+(c.reverse?'逆位':'正位'));b.nextElementSibling.innerHTML=`${c.name}<small>${c.reverse?'逆位 REVERSED':'正位 UPRIGHT'}</small>`;if(state.revealed.filter(Boolean).length===state.count){$('#read').disabled=false;$('#draw-status').textContent='所有牌已揭晓。让我们一起读懂它们的联系。'}})}
async function choose(i,button){if(!state.ready||state.busy||state.selected.length>=state.count||state.selected.includes(state.draw[i]))return;state.busy=true;const n=state.selected.length;state.selected.push(state.draw[i]);const from=button.getBoundingClientRect(),to=$(`#slot-${n} .placeholder`).getBoundingClientRect();const fly=document.createElement('div');fly.className='card fly';fly.innerHTML='<span class="back"></span>';Object.assign(fly.style,{left:from.left+'px',top:from.top+'px',width:from.width+'px',height:from.height+'px'});document.body.appendChild(fly);button.classList.add('picked');button.disabled=true;if(matchMedia(PHONE_QUERY).matches){phoneFlight(fly,from,to)}else{requestAnimationFrame(()=>requestAnimationFrame(()=>Object.assign(fly.style,{left:to.left+'px',top:to.top+'px',width:to.width+'px',height:to.height+'px'})));}await new Promise(r=>setTimeout(r,570));fly.remove();if(state.page!=='draw'){state.busy=false;return} $(`#slot-${n}`).innerHTML=selectedMarkup(n);state.busy=false;bindFlips();$('#draw-status').textContent=state.selected.length===state.count?'选择已完成。点击上方每张牌，亲手揭开牌面。':`已选 ${state.selected.length} / ${state.count} 张。继续选牌，或先翻开已选的牌。`;if(state.selected.length===state.count)document.querySelectorAll('.fan button').forEach(b=>b.disabled=true)}
function reading(){const data=createReadingData(state),prompt=buildAIPrompt(data);app.innerHTML=`<section class="page reading">${steps(2)}<div class="center reading-head"><p class="eyebrow">03 / A DIFFERENT PERSPECTIVE</p><h2>让牌面，成为一面镜子。</h2><p class="quote">${esc(state.question.trim()||topics[state.theme])}</p><span class="badge">固定牌义 · 可复制 AI 解牌提示词</span></div><div class="slots">${state.selected.map((c,i)=>`<div class="slot"><div class="slot-label">${position(i)}</div><div class="card flipped">${card(c,true)}</div><div class="card-caption">${c.name}<small>${c.reverse?'逆位 REVERSED':'正位 UPRIGHT'}</small></div></div>`).join('')}</div><div class="meanings" style="${state.count===1?'grid-template-columns:1fr':''}">${state.selected.map((c,i)=>`<article class="meaning"><p class="eyebrow">0${i+1} / ${position(i)} · 固定牌义</p><h3>${c.name} · ${c.reverse?'逆位':'正位'}</h3><p>${c.reverse?c.reversed:c.upright}。</p><p>牌位说明：${positionNotes[position(i)]}</p><p>单牌提示：${c.advice}</p></article>`).join('')}</div><article class="synthesis ai-reading" aria-labelledby="ai-title"><p class="eyebrow">A DEEPER CONVERSATION</p><h2 id="ai-title">AI 深度解牌</h2><p>将本次问题、牌位和真实牌面交给你选择的 AI，继续深入探索。提示词已包含本次抽牌数据与专业解读要求。</p><button class="primary wide" id="copy-prompt">一键复制 AI 解牌提示词</button><p id="copy-status" role="status" aria-live="polite"></p><details><summary>查看本次 AI 解牌提示词</summary><label for="ai-prompt" class="field-label">本次提示词（可选择并手动复制）</label><textarea id="ai-prompt" readonly spellcheck="false">${esc(prompt)}</textarea></details><p class="ai-note">本站仅生成提示词，不自动调用 AI，也不发送你的问题。复制后可自行粘贴到你选择的 AI 对话中。</p></article><p class="fine center">牌面提供反思视角，不代表已验证的现实事实或必然的未来。</p><div class="actions"><button class="primary" id="again">重新占卜 ⟲</button><button class="outline" id="share">分享结果 ↗</button></div><div id="share-fallback"></div></section>`;$('#copy-prompt').onclick=async()=>{const button=$('#copy-prompt'),status=$('#copy-status');button.disabled=true;try{await navigator.clipboard.writeText(prompt);status.textContent='✓ 提示词已复制，可粘贴到 AI 对话中继续解牌。';toast('AI 解牌提示词已复制')}catch{status.textContent='未能自动复制，请在下方长按或全选提示词后手动复制。';$('.ai-reading details').open=true;$('#ai-prompt').focus();$('#ai-prompt').select()}finally{button.disabled=false}};$('#again').onclick=()=>{state={page:'question',question:'',theme:'自我探索',count:3,draw:[],selected:[],revealed:[],ready:false,busy:false};go('question')};$('#share').onclick=async()=>{const text=`Tarot Atelier · ${state.question.trim()||topics[state.theme]}\n${state.selected.map((c,i)=>`${position(i)}：${c.name}（${c.reverse?'逆位':'正位'}）`).join('\n')}\n\n固定牌义与单牌提示\n${state.selected.map((c,i)=>`${position(i)}：${c.reverse?c.reversed:c.upright}。${c.advice}`).join('\n')}\n\n仅供自我反思。`;try{if(navigator.share){await navigator.share({title:'Tarot Atelier · 我的牌面',text});return}await navigator.clipboard.writeText(text);toast('结果已复制，可粘贴分享；网站仍保持私人访问。')}catch(e){if(e.name==='AbortError')return;$('#share-fallback').innerHTML=`<label class="field-label" for="sharetext">复制下方文字分享结果</label><textarea id="sharetext" readonly>${esc(text)}</textarea>`;$('#sharetext').select()}}}
function render(){disposeFan?.();disposeFan=null;if(state.page==='draw'&&!state.draw.length)state.page='question';if(state.page==='reading'&&state.revealed.filter(Boolean).length!==state.count)state.page='question';({home,question,draw,reading}[state.page]||home)()}
$('#about').onclick=()=>$('#info').showModal();$('.close').onclick=()=>$('#info').close();$('.brand').onclick=e=>{e.preventDefault();go('home')};history.replaceState({page:'home'},'','#home');window.onpopstate=()=>{state.page=location.hash.slice(1)||'home';render()};render();
